16	
17	`include "VX_define.vh"
18	
19	`IGNORE_UNUSED_BEGIN
20	
21	package VX_gpu_pkg;
22	
23	    // These 6 localparams mirror their VX_CFG_* macros, which expand to
24	    // VX_CFG_{DCACHE,L2,L3}_NUM_REQS — localparams declared later in this package.
25	    localparam DCACHE_NUM_BANKS                 = `VX_CFG_DCACHE_NUM_BANKS;
26	    localparam L1_MEM_PORTS                     = `VX_CFG_L1_MEM_PORTS;
27	    localparam L2_MEM_PORTS                     = `VX_CFG_L2_MEM_PORTS;
28	    localparam L2_NUM_BANKS                     = `VX_CFG_L2_NUM_BANKS;
29	    localparam L3_MEM_PORTS                     = `VX_CFG_L3_MEM_PORTS;
30	    localparam L3_NUM_BANKS                     = `VX_CFG_L3_NUM_BANKS;
31	
32	
33	    localparam NC_BITS = `CLOG2(`VX_CFG_NUM_CORES);
34	    localparam NW_BITS = `CLOG2(`VX_CFG_NUM_WARPS);
35	    localparam NT_BITS = `CLOG2(`VX_CFG_NUM_THREADS);
36	    localparam NB_BITS = `CLOG2(`VX_CFG_NUM_BARRIERS);
37	
38	    localparam NC_WIDTH = `UP(NC_BITS);
39	    localparam NW_WIDTH = `UP(NW_BITS);
40	    localparam NT_WIDTH = `UP(NT_BITS);
41	    localparam NB_WIDTH = `UP(NB_BITS);
42	
43	    localparam NUM_CTA_MAX = `VX_CFG_NUM_WARPS;
44	    localparam NCTA_BITS  = `CLOG2(NUM_CTA_MAX);
45	    localparam NCTA_WIDTH = `UP(NCTA_BITS);
46	
47	    localparam XLENB    = `VX_CFG_XLEN / 8;
48	    localparam XLENB_W  = `CLOG2(XLENB);
49	    localparam BYTESEL_BITS = (XLENB_W + XLENB_W);
50	    localparam [BYTESEL_BITS-1:0] BYTESEL_DEFAULT = {XLENB_W'(XLENB-1), XLENB_W'(0)};
51	
52	    localparam RV_REGS = 32;
53	    localparam RV_REGS_BITS = 5;
54	
55	    localparam RV_RD  = 0;
56	    localparam RV_RS1 = 1;
57	    localparam RV_RS2 = 2;
58	    localparam RV_RS3 = 3;
59	
60	    localparam REG_TYPE_I = 0;
61	    localparam REG_TYPE_F = 1;
62	
63	    localparam REG_TYPES = 1 + `VX_CFG_EXT_F_ENABLED;
64	
65	    localparam NUM_REGS = (REG_TYPES * RV_REGS);
66	
67	    localparam REG_TYPE_BITS = `LOG2UP(REG_TYPES);
68	
69	    localparam NUM_REGS_BITS = `CLOG2(NUM_REGS);
70	
71	    // Generic shadow-register namespace. Each bit is a slot that any
72	    // instruction class may claim for RAW/WAR hazard tracking via the
73	    // scoreboard's wr_xregs / rd_xregs masks. The decoder maps specific
74	    // semantics (fflags, frm, future TCU_LD metadata slots, etc.) to
75	    // these bits.
76	    localparam XREG_0      = 0;
77	    localparam XREG_1      = 1;
78	    localparam NUM_XREGS   = 2;
79	
80	    localparam DV_STACK_SIZE = `UP(`VX_CFG_NUM_THREADS-1);
81	    localparam DV_STACK_SIZEW = `LOG2UP(DV_STACK_SIZE);
82	
83	    localparam PERF_CTR_BITS = 44;
84	
85	    localparam SIMD_COUNT = `VX_CFG_NUM_THREADS / `VX_CFG_SIMD_WIDTH;
86	    localparam SIMD_IDX_BITS = `CLOG2(SIMD_COUNT);
87	    localparam SIMD_IDX_W = `UP(SIMD_IDX_BITS);
88	
89	    localparam NUM_OPCS_BITS = `CLOG2(`VX_CFG_NUM_OPCS);
90	    localparam NUM_OPCS_W = `UP(NUM_OPCS_BITS);
91	
92	    localparam BAR_ADDR_BITS = NW_BITS + NB_BITS;
93	    localparam BAR_ADDR_W = `UP(BAR_ADDR_BITS);
94	    localparam BAR_ID_SHIFT = 8;
95	
96	    localparam BAR_SIZE_W = `MAX(`MAX(NW_WIDTH, NC_WIDTH), `CLOG2(`VX_CFG_MAX_BAR_EVENTS));
97	
98	    localparam UOP_PACKLD = 0;
99	    localparam UOP_TCU = UOP_PACKLD + 1;
100	    localparam UOP_GFXW = UOP_TCU + `VX_CFG_EXT_TCU_ENABLED;
101	    localparam UOP_MAX = UOP_GFXW + `EXT_GFX_ANY_ENABLED;
102	    localparam UOP_CTR_W = 8;
103	
104	    localparam CTA_TID_WIDTH = `UP(NW_BITS + NT_BITS);
105	
106	`ifndef NDEBUG
107	    localparam UUID_WIDTH = 44;
108	`elsif SCOPE
109	    localparam UUID_WIDTH = 44;
110	`else
111	    localparam UUID_WIDTH = 1;
112	`endif
113	
114	`ifndef NDEBUG
115	    localparam PC_BITS = `VX_CFG_XLEN;
116	    function automatic logic [`VX_CFG_XLEN-1:0] to_fullPC(input logic[PC_BITS-1:0] pc);
117	        to_fullPC = `VX_CFG_XLEN'(pc);
118	    endfunction
119	    function automatic logic [PC_BITS-1:0] from_fullPC(input logic[`VX_CFG_XLEN-1:0] pc);
120	        from_fullPC = pc;
121	    endfunction
122	`elsif VX_CFG_EXT_C_ENABLE
123	    // With the compressed extension, branch targets and warp PCs may be 2-byte aligned.
124	    localparam PC_BITS = (`VX_CFG_XLEN-1);
125	    function automatic logic [`VX_CFG_XLEN-1:0] to_fullPC(input logic[PC_BITS-1:0] pc);
126	        to_fullPC = `VX_CFG_XLEN'({pc, 1'b0});
127	    endfunction
128	    function automatic logic [PC_BITS-1:0] from_fullPC(input logic[`VX_CFG_XLEN-1:0] pc);
129	        from_fullPC = PC_BITS'(pc >> 1);
130	    endfunction
131	`else
132	    localparam PC_BITS = (`VX_CFG_XLEN-2);
133	    function automatic logic [`VX_CFG_XLEN-1:0] to_fullPC(input logic[PC_BITS-1:0] pc);
134	        to_fullPC = `VX_CFG_XLEN'({pc, 2'b0});
135	    endfunction
136	    function automatic logic [PC_BITS-1:0] from_fullPC(input logic[`VX_CFG_XLEN-1:0] pc);
137	        from_fullPC = PC_BITS'(pc >> 2);
138	    endfunction
139	`endif
140	
141	    localparam NUM_SRC_OPDS = 3;
142	    localparam SRC_OPD_BITS = `CLOG2(NUM_SRC_OPDS);
143	    localparam SRC_OPD_WIDTH = `UP(SRC_OPD_BITS);
144	    localparam NUM_SOCKETS = `UP(`VX_CFG_NUM_CORES / `VX_CFG_SOCKET_SIZE);
145	
146	
147	    // ===== AMO (RVA) sideband =====================================
148	    // Fields are only meaningful when amo_valid==1; the bank's reservation
149	    // table keys on hart_id = make_hart_id(cid, wid, tid).
150	    // MINU/MAXU collapse into MIN/MAX + amo_unsigned.
151	
152	    // make_hart_id(cid, wid, tid) — packed concatenation, low bits = tid.
153	    localparam HART_ID_BITS = NC_BITS + NW_BITS + NT_BITS;
154	    localparam HART_ID_WIDTH = `UP(HART_ID_BITS);
155	
156	    // ───────────────────────────────────────────────────────────────────────
157	    // `mem_bus_attr_t` — single attr type shared by every memory bus.
158	    // VX_lsu_mem_if carries it per-lane via req_data.user.
159	    // VX_mem_bus_if carries one scalar mem_bus_attr_t per request via req_data.attr.
160	    //
161	    // Field order is LOAD-BEARING: MEM_ATTR_*_OFFS localparams depend
162	    // on it. Don't reorder without updating offsets.
163	    // ───────────────────────────────────────────────────────────────────────
164	
165	    // Typed AMO opcode enum. Defined unconditionally so AMO_ENABLE can be a
166	    // parameter (not ifdef) on the cache hierarchy. When EXT_A_ENABLE is
167	    // undefined, the struct bits are still allocated in the attr field but
168	    // the cache's AMO logic is generated away by AMO_ENABLE=0.
169	    typedef enum logic [3:0] {
170	        AMO_OP_LR    = 4'h0,
171	        AMO_OP_SC    = 4'h1,
172	        AMO_OP_ADD   = 4'h2,
173	        AMO_OP_SWAP  = 4'h3,
174	        AMO_OP_XOR   = 4'h4,
175	        AMO_OP_OR    = 4'h5,
176	        AMO_OP_AND   = 4'h6,
177	        AMO_OP_MIN   = 4'h7,
178	        AMO_OP_MAX   = 4'h8
179	        // MINU/MAXU collapse into MIN/MAX + amo_unsigned bit.
180	    } amo_op_e;
181	
182	    // Slim AMO sideband. width derives from byteen popcount at the cache
183	    // bank; rhs is read from the request's data field. Includes scalar
184	    // hart_id for the LLC reservation table.
185	    typedef struct packed {
186	        logic [HART_ID_WIDTH-1:0]   hart_id;
187	        logic                        amo_unsigned;
188	        amo_op_e                     amo_op;
189	        logic                        amo_valid;
190	    } amo_req_t;
191	    localparam AMO_REQ_BITS = $bits(amo_req_t);
192	
193	    // Cross-cache mem-bus attr — FIXED OFFSETS so arbitration is clean.
194	    // Shared by every VX_mem_bus_if instance that carries attr.
195	    // is_flush at LSB so dcr_flush can drive it deterministically.
196	    typedef struct packed {
197	        amo_req_t                    amo;          // at MEM_ATTR_AMO_OFFS=3 (valid + op + unsigned + hart_id)
198	        logic                        is_addr_local; // MEM_ATTR_LOCAL_OFFS = 2
199	        logic                        is_addr_io;    // MEM_ATTR_IO_OFFS    = 1
200	        logic                        is_flush;      // MEM_ATTR_FLUSH_OFFS = 0
201	    } mem_bus_attr_t;
202	
203	    // FIXED bit-position offsets — invariant across all VX_mem_bus_if
204	    // instances and cache levels. Don't change without coordinating
205	    // every cache/source/arbiter that touches attr.
206	    // The amo bits are always allocated; AMO_ENABLE on the cache controls
207	    // whether AMO logic is generated, not whether the field is present.
208	    localparam MEM_ATTR_FLUSH_OFFS  = 0;
209	    localparam MEM_ATTR_IO_OFFS     = 1;
210	    localparam MEM_ATTR_LOCAL_OFFS  = 2;
211	    localparam MEM_ATTR_AMO_OFFS    = 3;        // amo_req_t cast site (valid + op + unsigned + hart_id)
212	
213	    // Total width of the mem-bus attr field. Use this as the parameter
214	    // default for VX_mem_bus_if's ATTR_WIDTH parameter and as the
215	    // wire/reg sizing for any per-cache plumbing.
216	    localparam MEM_ATTR_WIDTH = $bits(mem_bus_attr_t);
217	
218	    localparam VX_DCR_ADDR_WIDTH = `VX_DCR_ADDR_BITS;
219	    localparam VX_DCR_DATA_WIDTH = `VX_DCR_DATA_BITS;
220	
221	`ifdef VX_DBG_STALL_TIMEOUT
