1480	    ////////////////////////// RTU / RTcache Parameters ///////////////////////
1481	`ifdef VX_CFG_EXT_RTU_ENABLE
1482	    localparam RTU_REQ_QUEUE_SIZE     = 4;
1483	    localparam RTU_REQ_TAG_WIDTH      = (UUID_WIDTH + `CLOG2(RTU_REQ_QUEUE_SIZE));
1484	    localparam RTU_REQ_ARB1_TAG_WIDTH = (RTU_REQ_TAG_WIDTH + `CLOG2(`VX_CFG_SOCKET_SIZE));
1485	    localparam RTU_REQ_ARB2_TAG_WIDTH = (RTU_REQ_ARB1_TAG_WIDTH + `ARB_SEL_BITS(NUM_SOCKETS, `VX_CFG_NUM_RTU_CORES));
1486	
1487	    // The RTU fetches a whole CW-BVH node (one 64 B cache line) per request,
1488	    // so its cache is line-granular: word size == line size, one port/core.
1489	    localparam RTCACHE_WORD_SIZE     = `VX_CFG_L1_LINE_SIZE;
1490	    localparam RTCACHE_ADDR_WIDTH    = (`VX_CFG_MEM_ADDR_WIDTH - `CLOG2(RTCACHE_WORD_SIZE));
1491	    localparam RTCACHE_LINE_SIZE     = `VX_CFG_L1_LINE_SIZE;
1492	    localparam RTCACHE_NUM_REQS      = 1;
1493	    localparam RTCACHE_TAG_ID_BITS   = `CLOG2(`VX_CFG_RTCACHE_MSHR_SIZE);
1494	    localparam RTCACHE_TAG_WIDTH     = (UUID_WIDTH + RTCACHE_TAG_ID_BITS);
1495	    localparam RTCACHE_BUS_TAG_WIDTH = (RTCACHE_TAG_WIDTH + 1);
1496	    localparam RTCACHE_MEM_DATA_WIDTH= (RTCACHE_LINE_SIZE * 8);
1497	    localparam RTCACHE_MEM_PORTS     = 1;
1498	    localparam RTCACHE_MEM_TAG_WIDTH = `CACHE_CLUSTER_MEM_TAG_WIDTH(
1499	        `VX_CFG_RTCACHE_MSHR_SIZE, `VX_CFG_RTCACHE_NUM_BANKS, RTCACHE_MEM_PORTS, `VX_CFG_NUM_RTCACHES, UUID_WIDTH);
1500	`endif
1501	
1502	    /////////////////////////////// L1 Parameters /////////////////////////////
1503	
1504	    // arbitrate between icache and dcache
1505	    localparam L1_MEM_TAG_WIDTH     = `MAX(ICACHE_MEM_TAG_WIDTH, DCACHE_MEM_TAG_WIDTH);
1506	    localparam L1_MEM_ARB_TAG_WIDTH = (L1_MEM_TAG_WIDTH + `CLOG2(2));
1507	
1508	    /////////////////////////////// L2 Parameters /////////////////////////////
1509	
1510	    localparam ICACHE_MEM_ARB_IDX   = 0;
1511	    localparam DCACHE_MEM_ARB_IDX   = ICACHE_MEM_ARB_IDX + 1;
1512	
1513	    // Word size in bytes
1514	    localparam L2_WORD_SIZE	        = `VX_CFG_L1_LINE_SIZE;
1515	
1516	    // Sector = mem transaction granule (= line when 1 sector/line)
1517	    localparam L2_SECTOR_SIZE       = `VX_CFG_L2_SECTOR_SIZE;
1518	
1519	    // Input request size — socket-only (DXA merges via per-port priority arb)
1520	    localparam L2_SOCKET_REQS       = NUM_SOCKETS * L1_MEM_PORTS;
1521	
1522	    // Graphics caches add dedicated L2 input slots (one per enabled cache)
1523	    localparam L2_GFX_REQS          = `VX_CFG_EXT_TEX_ENABLED + `VX_CFG_EXT_RASTER_ENABLED + `VX_CFG_EXT_OM_ENABLED + `VX_CFG_EXT_RTU_ENABLED;
1524	    localparam L2_GFX_TEX_IDX       = L2_SOCKET_REQS;
1525	    localparam L2_GFX_RASTER_IDX    = L2_GFX_TEX_IDX + `VX_CFG_EXT_TEX_ENABLED;
1526	    localparam L2_GFX_OM_IDX        = L2_GFX_RASTER_IDX + `VX_CFG_EXT_RASTER_ENABLED;
1527	    localparam L2_GFX_RTU_IDX       = L2_GFX_OM_IDX + `VX_CFG_EXT_OM_ENABLED;
1528	
1529	    localparam L2_NUM_REQS          = L2_SOCKET_REQS + L2_GFX_REQS;
1530	
1531	`ifdef VX_CFG_EXT_DXA_ENABLE
1532	  `ifdef VX_CFG_NUM_DXA_CORES
1533	    localparam L2_DXA_NUM_REQS      = `VX_CFG_NUM_DXA_CORES;
1534	  `else
1535	    localparam L2_DXA_NUM_REQS      = 1;
1536	  `endif
1537	`else
1538	    localparam L2_DXA_NUM_REQS      = 0;
1539	`endif
1540	    // DXA uses a fixed small number of L2 ports (= NUM_DXA_UNITS) to avoid
1541	    // a combinational ready-valid loop when output-select distribution fans
1542	    // out 1 worker across many L2 ports in multi-core configs.
1543	    localparam DXA_L2_GMEM_PORTS    = `MIN(L2_DXA_NUM_REQS, L2_SOCKET_REQS);
1544	    localparam DXA_L2_ARB_TAG_BITS  = `VX_CFG_EXT_DXA_ENABLED * `CLOG2(2);
1545	
1546	    // Core request tag bits (includes DXA arb overhead when enabled)
1547	    localparam L2_TAG_WIDTH         = L1_MEM_ARB_TAG_WIDTH + DXA_L2_ARB_TAG_BITS;
1548	
1549	    // Memory request data bits (mem transacts in sectors)
1550	    localparam L2_MEM_DATA_WIDTH	= (L2_SECTOR_SIZE * 8);
1551	
1552	    // Memory request tag bits
1553	`ifdef VX_CFG_L2_ENABLE
1554	    localparam L2_MEM_TAG_WIDTH     = `CACHE_NC_MEM_TAG_WIDTH(`VX_CFG_L2_MSHR_SIZE, L2_NUM_BANKS, L2_NUM_REQS, L2_MEM_PORTS, L2_SECTOR_SIZE, L2_WORD_SIZE, L2_TAG_WIDTH, UUID_WIDTH);
1555	`else
1556	    localparam L2_MEM_TAG_WIDTH     = `CACHE_BYPASS_TAG_WIDTH(L2_NUM_REQS, L2_MEM_PORTS, L2_SECTOR_SIZE, L2_WORD_SIZE, L2_TAG_WIDTH);
1557	`endif
1558	
1559	    // L2 is the LLC iff L2 is enabled and L3 is not.
1560	    localparam L2_IS_LLC            = `VX_CFG_L2_ENABLED && !`VX_CFG_L3_ENABLED;
1561	
1562	    /////////////////////////////// L3 Parameters /////////////////////////////
1563	
1564	    // Word size in bytes (= L2 mem transaction granule = L2 sector)
1565	    localparam L3_WORD_SIZE	        = L2_SECTOR_SIZE;
1566	
1567	    // Sector = mem transaction granule (= line when 1 sector/line)
1568	    localparam L3_SECTOR_SIZE       = `VX_CFG_L3_SECTOR_SIZE;
1569	
1570	    // Input request size
1571	    localparam L3_NUM_REQS	        = `VX_CFG_NUM_CLUSTERS * L2_MEM_PORTS;
1572	
1573	    // Core request tag bits
1574	    localparam L3_TAG_WIDTH	        = L2_MEM_TAG_WIDTH;
1575	
1576	    // Memory request data bits (mem transacts in sectors)
1577	    localparam L3_MEM_DATA_WIDTH	= (L3_SECTOR_SIZE * 8);
1578	
1579	    // Memory request tag bits
1580	`ifdef VX_CFG_L3_ENABLE
1581	    localparam L3_MEM_TAG_WIDTH     = `CACHE_NC_MEM_TAG_WIDTH(`VX_CFG_L3_MSHR_SIZE, L3_NUM_BANKS, L3_NUM_REQS, L3_MEM_PORTS, L3_SECTOR_SIZE, L3_WORD_SIZE, L3_TAG_WIDTH, UUID_WIDTH);
1582	`else
1583	    localparam L3_MEM_TAG_WIDTH     = `CACHE_BYPASS_TAG_WIDTH(L3_NUM_REQS, L3_MEM_PORTS, L3_SECTOR_SIZE, L3_WORD_SIZE, L3_TAG_WIDTH);
1584	`endif
1585	    // L3 is the LLC whenever it is enabled.
1586	    localparam L3_IS_LLC            = `VX_CFG_L3_ENABLED;
1587	
1588	    ///////////////////////////////////////////////////////////////////////////
1589	
1590	    localparam VX_MEM_PORTS =           L3_MEM_PORTS;
1591	    localparam VX_MEM_BYTEEN_WIDTH =    L3_SECTOR_SIZE;
1592	    localparam VX_MEM_ADDR_WIDTH =      (`VX_CFG_MEM_ADDR_WIDTH - `CLOG2(L3_SECTOR_SIZE));
1593	    localparam VX_MEM_DATA_WIDTH =      (L3_SECTOR_SIZE * 8);
1594	    localparam VX_MEM_TAG_WIDTH =       L3_MEM_TAG_WIDTH;
1595	
1596	    ///////////////////////// Miscaellaneous functions ////////////////////////
1597	
1598	    function automatic logic [SFU_WIDTH-1:0] op_to_sfu_type(
1599	        input logic [INST_OP_BITS-1:0] op_type
1600	    );
1601	        case (op_type)
1602	            INST_SFU_CSRRW,
1603	            INST_SFU_CSRRS,
1604	            INST_SFU_CSRRC: op_to_sfu_type = SFU_CSRS;
1605	            default: op_to_sfu_type = SFU_WCTL;
1606	        endcase
1607	    endfunction
1608	
1609	    function automatic logic [NUM_REGS_BITS-1:0] make_reg_num(input logic [REG_TYPE_BITS-1:0] rtype, logic [RV_REGS_BITS-1:0] idx);
1610	        return (NUM_REGS_BITS'(rtype) << RV_REGS_BITS) | NUM_REGS_BITS'(idx);
1611	    endfunction
1612	
1613	    function automatic logic [REG_TYPE_BITS-1:0] get_reg_type(input logic [NUM_REGS_BITS-1:0] reg_num);
1614	        return REG_TYPE_BITS'(reg_num >> RV_REGS_BITS);
1615	    endfunction
1616	
1617	    function automatic logic [RV_REGS_BITS-1:0] get_reg_idx(input logic [NUM_REGS_BITS-1:0] reg_num);
1618	        return reg_num[RV_REGS_BITS-1:0];
1619	    endfunction
1620	
1621	    function automatic logic [UUID_WIDTH-1:0] get_uop_uuid(input logic [UUID_WIDTH-1:0] uuid, input logic [UOP_CTR_W-1:0] uop_idx);
1622	    `ifdef UUID_ENABLE
1623	        logic [31:0] uuid_lo = {uop_idx[0 +: UOP_CTR_W], uuid[0 +: (32 - UOP_CTR_W)]};
1624	        return {uuid[UUID_WIDTH-1:32], uuid_lo};
1625	    `else
1626	        return uuid;
1627	    `endif
1628	    endfunction
1629	
1630	endpackage
1631	
1632	`IGNORE_UNUSED_END
1633	
1634	`endif // VX_GPU_PKG_VH
1635

