        logic is_first_uop;   // WGMMA: set on first sub-uop of an expansion
        logic a_from_smem;    // 0=register, 1=shared memory (B is always smem)
        logic [1:0] cd_nregs; // 0=8, 1=16, 2=32 C/D registers
        logic [4:0] fmt_d;
        logic [4:0] fmt_s;
        logic [3:0] step_k;
        logic [3:0] step_n;
